"""Regenerate the 'Content gaps' section of coverage/known-gaps.md from the matrix `gaps` column.

Usage: python gaps_report.py [--root DIR]
Only the text between the gaps markers is rewritten; everything else in known-gaps.md is kept.
"""
import sys
from pathlib import Path

from _common import load_matrix

START, END = "<!-- gaps:start -->", "<!-- gaps:end -->"


def update_gaps_section(root):
    root = Path(root)
    rows = [r for r in load_matrix(root) if r["gaps"].strip()]
    lines = [START,
             "Generated by `scripts/gaps_report.py` from the original book's coverage matrix; "
             "do not edit between the markers. Each entry is a minor, recorded limitation (usually a table or "
             "figure clipped in the PDF itself, an estimate read from a chart, or a printed inconsistency in "
             "the book). The affected statement is marked `UNVERIFIED:` or labelled as an estimate in the module.",
             ""]
    lines += [f"- **{r['id']}** ({r['section_path'].split(' > ')[-1]}, PDF pp. {r['start_page']}-{r['end_page']}): "
              f"{r['gaps'].strip()}" for r in rows]
    lines += ["", END]
    block = "\n".join(lines)
    f = root / "coverage" / "known-gaps.md"
    text = f.read_text(encoding="utf-8") if f.exists() else "# Known gaps register\n"
    if START in text and END in text:
        head, rest = text.split(START, 1)
        _, tail = rest.split(END, 1)
        text = head + block + tail
    else:
        text = text.rstrip("\n") + "\n\n## Content gaps\n\n" + block + "\n"
    f.write_text(text, encoding="utf-8")
    return len(rows)


def main(argv):
    root = Path(argv[argv.index("--root") + 1]) if "--root" in argv else Path(__file__).resolve().parent.parent
    print(f"gaps_report: {update_gaps_section(root)} row(s) with recorded gaps")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
